values
  ('92e7e3c1-fcf0-489d-9f15-fd92df5a02e6', 'a1b2c3d4-5e6f-4b40-9d90-0e1f2a3b4c00', null, 'topic'::public.curated_course_node_type, 'What Medieval Literature Is: Periods, Languages, Genres, and Material Texts', 'This opening unit frames medieval literature as a multilingual, manuscript-based, performance-rich field rather than a single national canon. Students learn how periodization, language, manuscript survival, translation, and modern editing shape what we read.', 0),
  ('284ce85d-43bd-4ec4-9db5-71ef3e798b4f', 'a1b2c3d4-5e6f-4b40-9d90-0e1f2a3b4c00', '92e7e3c1-fcf0-489d-9f15-fd92df5a02e6', 'subtopic'::public.curated_course_node_type, 'Periodization and field map', 'Students learn the broad timeline and why ''medieval'' is a scholarly category with flexible boundaries.', 0),
