  ('76dd3ec1-4a15-4d8b-a21a-51dd8efa59c4', 'a1b2c3d4-5e6f-4b40-9d90-0e1f2a3b4c00', null, 'topic'::public.curated_course_node_type, 'Old English Elegy, Wisdom, and Religious Writing', 'Students move beyond epic to elegies, saints'' lives, biblical poems, homilies, riddles, and wisdom literature. The point is to see Old English writing as emotionally varied and intellectually rich.', 3),
