  ('a41360da-f239-4ddf-a50d-019916fa703f', 'a1b2c3d4-5e6f-4b40-9d90-0e1f2a3b4c00', null, 'topic'::public.curated_course_node_type, 'Conquest, Multilingual England, and the Rise of Middle English', 'This unit explains how the Norman Conquest and multilingual institutions reshaped literary production. Students learn that Middle English literature emerges from contact among languages, classes, regions, and genres.', 4),
