  'Medieval Literature',
  'Medieval Literature introduces students to major Old and Middle English texts, genres, languages, and manuscript cultures from the Anglo-Saxon period through the later Middle Ages. Students read heroic poetry, elegy, romance, Chaucer, allegory, religious writing, drama, prose, women''s visionary writing, and Arthurian tradition while learning how manuscript transmission, multilingual England, performance, translation, and modern reception shape interpretation. The course combines close reading with historical context, basic Middle English reading skills, material-text awareness, and research methods.',
  $medljson${"slug": "medieval-literature", "title": "Medieval Literature", "description": "Medieval Literature introduces students to major Old and Middle English texts, genres, languages, and manuscript cultures from the Anglo-Saxon period through the later Middle Ages. Students read heroic poetry, elegy, romance, Chaucer, allegory, religious writing, drama, prose, women's visionary writing, and Arthurian tradition while learning how manuscript transmission, multilingual England, performance, translation, and modern reception shape interpretation. The course combines close reading with historical context, basic Middle English reading skills, material-text awareness, and research methods.", "topics": [{"id": "92e7e3c1-fcf0-489d-9f15-fd92df5a02e6", "type": "topic", "title": "What Medieval Literature Is: Periods, Languages, Genres, and Material Texts", "description": "This opening unit frames medieval literature as a multilingual, manuscript-based, performance-rich field rather than a single national canon. Students learn how periodization, language, manuscript survival, translation, and modern editing shape what we read.", "children": [{"id": "284ce85d-43bd-4ec4-9db5-71ef3e798b4f", "type": "subtopic", "title": "Periodization and field map", "children": [{"id": "c8fd035a-0497-440b-bb48-b45856eeadf8", "type": "concept", "title": "early medieval, high medieval, and late medieval frames"}, {"id": "38efcc76-fe24-42d2-86b4-ed13614d5ee7", "type": "concept", "title": "Anglo-Saxon, Anglo-Norman, and Middle English contexts"}, {"id": "a458447d-9ad1-4f1d-9e95-5dfe2469390c", "type": "concept", "title": "continuity into early modern print culture"}, {"id": "d5519753-cafb-4214-b146-da02c61f5960", "type": "concept", "title": "medieval studies as interdisciplinary field"}], "description": "Students learn the broad timeline and why 'medieval' is a scholarly category with flexible boundaries."}, {"id": "63a4db2e-ec3a-49c0-9205-520f96ac272b", "type": "subtopic", "title": "Languages of medieval England", "children": [{"id": "f28067f9-9066-4f1d-8e39-4014544c6bb9", "type": "concept", "title": "Old English and Middle English"}, {"id": "65223dfa-5789-45e9-bbea-dcbe85474a5a", "type": "concept", "title": "Latin clerical culture"}, {"id": "706d995e-6cd0-4dce-8095-c1530896082b", "type": "concept", "title": "Anglo-Norman French"}, {"id": "f2fca2f0-b1db-4cbf-8702-a87496eaf135", "type": "concept", "title": "dialect and language change"}], "description": "The goal is to understand English literature in relation to Latin, French, Norse, Celtic, and multilingual exchange."}, {"id": "2e9b8bc9-d839-4663-b35d-5d8d1b48946c", "type": "subtopic", "title": "Manuscript and genre awareness", "children": [{"id": "943e61f3-a49c-4b65-9bcf-e44f17d21d8c", "type": "concept", "title": "codex versus printed book"}, {"id": "8b160bfd-ef7b-4070-8661-a15e0a807504", "type": "concept", "title": "scribes and patrons"}, {"id": "0f3145fe-c54d-413c-8e97-9d223d178cc0", "type": "concept", "title": "genre as social practice"}, {"id": "6a003e1d-70ef-459a-8a86-9285f90b2256", "type": "concept", "title": "translation and adaptation"}], "description": "Students begin treating texts as artifacts that circulated in specific books, communities, and performance settings."}]}, {"id": "ab389ceb-5564-4d1a-9236-4934a52fe752", "type": "topic", "title": "Old English Literary Culture and Anglo-Saxon Worlds", "description": "Students enter the early medieval English world through language, history, religion, heroic culture, and manuscript survival. The emphasis is on reading Old English literature as art, memory, and cultural negotiation.", "children": [{"id": "d4cf0a93-aa90-447b-b245-3c447921df69", "type": "subtopic", "title": "Anglo-Saxon historical context", "children": [{"id": "d6daae7d-1255-43d6-9596-2ce6773e6529", "type": "concept", "title": "migration and settlement narratives"}, {"id": "8dd1d998-1585-47f4-8efe-10a4ded9cda9", "type": "concept", "title": "conversion to Christianity"}, {"id": "dafa9a51-490d-430d-b24c-2a843fef2c22", "type": "concept", "title": "monastic learning"}, {"id": "9ec64d32-c264-4459-8e24-2de65c177a78", "type": "concept", "title": "kingdoms, warfare, and law"}], "description": "Students learn the cultural and political background needed to understand early English texts."}, {"id": "06c55dcc-60fa-4097-908d-9778b2164d0d", "type": "subtopic", "title": "Old English language and poetics", "children": [{"id": "61d8b646-8374-430a-ba3e-25cb7dac769e", "type": "concept", "title": "alliterative meter"}, {"id": "62927ead-7dd3-4823-bd7d-a7eea00b2d71", "type": "concept", "title": "kennings and compounds"}, {"id": "daa1f62a-7cc8-420b-a7d6-e59fb2cd99c2", "type": "concept", "title": "variation and apposition"}, {"id": "4d9258d8-aa4f-4db6-b787-3fa6a34631cd", "type": "concept", "title": "formulaic composition"}], "description": "Students gain a working sense of Old English sound, form, and poetic technique."}, {"id": "10fc2fab-c826-4da8-b93d-0d0481090aa0", "type": "subtopic", "title": "Manuscript survival", "children": [{"id": "842cf6ca-7493-4385-9a75-caa93e136e0f", "type": "concept", "title": "Exeter Book"}, {"id": "5c00f595-d242-4b73-a57e-cd56185c38f1", "type": "concept", "title": "Nowell Codex"}, {"id": "97d33b75-b0ac-47e4-bd65-1f1f87e2d97b", "type": "concept", "title": "Vercelli Book"}, {"id": "71bc71c5-ee3f-41c6-8931-83b1a9e2bffa", "type": "concept", "title": "Junius Manuscript"}], "description": "Students learn why only some texts survive and how major codices shape the field."}]}, {"id": "30804cac-f323-4186-92e2-4c37d15caaec", "type": "topic", "title": "Beowulf and Heroic Poetry", "description": "This unit centers Beowulf as a major Old English poem and a gateway to heroic ethics, kinship, feud, monstrosity, memory, and Christian-pagan interpretive tension.", "children": [{"id": "d4c04cfc-3d32-416f-b6a2-bd46233aba7d", "type": "subtopic", "title": "Heroic culture and social order", "children": [{"id": "9b7c9239-364e-4281-8db6-80301f7a3d31", "type": "concept", "title": "comitatus and lordship"}, {"id": "467e2e28-0c02-465b-811a-464bdaa5f350", "type": "concept", "title": "gift exchange"}, {"id": "b1613870-6920-4d9a-97dc-70cc1edd24d9", "type": "concept", "title": "feud and justice"}, {"id": "a4de27f2-4072-407d-bf1d-9743ef451e1e", "type": "concept", "title": "fame, memory, and mortality"}], "description": "Students analyze how the poem imagines loyalty, treasure, fame, vengeance, and communal survival."}, {"id": "a1cdef70-679a-48ad-88c3-40efafc0b443", "type": "subtopic", "title": "Monsters and boundaries", "children": [{"id": "c7de4d2b-a26d-48a9-ae6f-ccdb2408a61b", "type": "concept", "title": "exile and kinship"}, {"id": "c0ef0ffc-3211-4c21-88f4-9e636e17e12a", "type": "concept", "title": "hall and wilderness"}, {"id": "97a77809-dbfc-48c7-9433-a4a72de21466", "type": "concept", "title": "gendered monstrosity"}, {"id": "09cf6429-6e1f-456b-b9c1-709586ba18c4", "type": "concept", "title": "dragon hoard and historical loss"}], "description": "Students learn how Grendel, Grendel's mother, and the dragon test social, spiritual, and symbolic boundaries."}, {"id": "790f0804-b0d3-45dc-bcc0-e65aed618a4d", "type": "subtopic", "title": "Christianity, pagan memory, and translation", "children": [{"id": "c23211bb-f445-47f8-a0fe-f314574842ad", "type": "concept", "title": "biblical allusion"}, {"id": "6a7f31a6-6bb0-4bd2-bb84-800922ede7f1", "type": "concept", "title": "wyrd and providence"}, {"id": "e6eb1b87-5aac-4e39-8123-4da60b7b935e", "type": "concept", "title": "translation choices"}, {"id": "7c90e144-19f4-4699-8eeb-ea20d1fc819a", "type": "concept", "title": "modern reception of Beowulf"}], "description": "Students examine how the poem stages religious and historical distance."}]}, {"id": "76dd3ec1-4a15-4d8b-a21a-51dd8efa59c4", "type": "topic", "title": "Old English Elegy, Wisdom, and Religious Writing", "description": "Students move beyond epic to elegies, saints' lives, biblical poems, homilies, riddles, and wisdom literature. The point is to see Old English writing as emotionally varied and intellectually rich.", "children": [{"id": "5701afd5-9e81-4c8a-b331-31238545f73c", "type": "subtopic", "title": "Elegy and exile", "children": [{"id": "b42af383-3f92-4bf0-9eee-c784b07ae8b7", "type": "concept", "title": "The Wanderer"}, {"id": "19339ce7-e77b-4945-8fd2-9a383650846c", "type": "concept", "title": "The Seafarer"}, {"id": "36831350-bae6-482c-ada9-e6882be51db7", "type": "concept", "title": "The Wife's Lament"}, {"id": "6b0d9672-5fae-450d-beb9-b45e62e906cf", "type": "concept", "title": "ruin and transience"}], "description": "Students learn how poems of loss, wandering, and memory create distinctive emotional landscapes."}, {"id": "51300c9f-3d39-43f6-97fa-23a0c57f7278", "type": "subtopic", "title": "Riddle, wisdom, and learning", "children": [{"id": "19eda115-57db-4d93-9170-ffdecbb1caf9", "type": "concept", "title": "Exeter Book riddles"}, {"id": "373d3989-40d1-40e6-810c-725035956628", "type": "concept", "title": "gnomic verse"}, {"id": "ff2740e4-d285-48e3-bb5f-cbfd295f80d0", "type": "concept", "title": "voice and personification"}, {"id": "c5ebf442-6712-4ef7-a569-fc08557ca92a", "type": "concept", "title": "knowledge and secrecy"}], "description": "Students study playful, learned, and philosophical forms of early medieval thought."}, {"id": "66096c55-e00c-4adc-bfc4-dc6d3c7ad4a9", "type": "subtopic", "title": "Religious prose and poetry", "children": [{"id": "7563a1bb-bdb5-40ad-8434-1f0e49df65bd", "type": "concept", "title": "saints' lives"}, {"id": "cbfd32fb-1411-4ecd-a50e-c65c498f9417", "type": "concept", "title": "homilies"}, {"id": "205dfa39-d4d3-4d01-ad81-a46bebdc25aa", "type": "concept", "title": "biblical paraphrase"}, {"id": "d0633fbe-be9e-4c77-9943-b7eb71e0533d", "type": "concept", "title": "cross and vision poetry"}], "description": "Students connect literary form to devotion, teaching, and ecclesiastical culture."}]}, {"id": "a41360da-f239-4ddf-a50d-019916fa703f", "type": "topic", "title": "Conquest, Multilingual England, and the Rise of Middle English", "description": "This unit explains how the Norman Conquest and multilingual institutions reshaped literary production. Students learn that Middle English literature emerges from contact among languages, classes, regions, and genres.", "children": [{"id": "c446a653-b44b-437d-857c-f9882392d64e", "type": "subtopic", "title": "Norman Conquest and literary change", "children": [{"id": "71c38bad-f026-461c-ab86-2563caa5f125", "type": "concept", "title": "English, French, and Latin after 1066"}, {"id": "933629b8-c6e7-4be7-8440-b3577afd9957", "type": "concept", "title": "court and clerical culture"}, {"id": "c00fc634-e6f4-4a8f-b32b-d1fd3c1f3744", "type": "concept", "title": "administration and literacy"}, {"id": "7b5b7803-3f29-4a14-8047-09642c3ce6cb", "type": "concept", "title": "translation as cultural negotiation"}], "description": "Students examine how conquest changed patronage, language hierarchy, law, and textual circulation."}, {"id": "7b2daaa9-04d3-4295-b15d-dda27792933a", "type": "subtopic", "title": "Middle English dialects and reading skills", "children": [{"id": "3f651e86-11a0-4ce9-aca1-107daa7665eb", "type": "concept", "title": "dialect variation"}, {"id": "6faaf020-66b6-489c-beeb-b7e3f8a2e47a", "type": "concept", "title": "pronunciation and final-e"}, {"id": "808be5b9-42ae-4078-b3df-73c77e80004f", "type": "concept", "title": "glosses and dictionaries"}, {"id": "fef482a2-ff91-46f5-9c34-e9d58897bc51", "type": "concept", "title": "reading aloud"}], "description": "Students develop strategies for reading Middle English without treating it as merely difficult modern English."}, {"id": "5cbf0cbd-fa31-4d3e-9902-ba886ca5ce86", "type": "subtopic", "title": "Translation and adaptation", "children": [{"id": "9844ee1c-7305-46b3-9391-24783e5e5eb2", "type": "concept", "title": "Latin sources"}, {"id": "065f102d-83bc-4ef4-9fc3-e84a580679f4", "type": "concept", "title": "French romance"}, {"id": "b2399e6c-9bef-4811-90b4-7cca77972c39", "type": "concept", "title": "biblical and devotional translation"}, {"id": "eb107c8f-aeb4-496d-b364-bbb107fb8635", "type": "concept", "title": "adaptation and authority"}], "description": "Students learn how medieval authors remake inherited material for new audiences."}]}, {"id": "e34067d9-9e3f-44aa-832c-4332563b3c08", "type": "topic", "title": "Middle English Romance and Sir Gawain and the Green Knight", "description": "Romance gives students a way into chivalry, desire, marvels, courtly identity, testing, and moral ambiguity. Sir Gawain anchors the unit as a formally brilliant poem about performance, failure, and self-knowledge.", "children": [{"id": "e6dc3dbb-59ff-4cfd-8755-39fcd1f7874a", "type": "subtopic", "title": "Romance conventions", "children": [{"id": "ae60c1da-8173-415f-a727-4205f87e58c1", "type": "concept", "title": "quest structure"}, {"id": "a0794554-994f-4453-b74d-9201931869d8", "type": "concept", "title": "court and wilderness"}, {"id": "104177dd-6097-4945-9467-c5b264f4e346", "type": "concept", "title": "marvels and enchantment"}, {"id": "747ee65f-4812-4ec8-a1fa-e9080e254bde", "type": "concept", "title": "honor and reputation"}], "description": "Students learn the narrative grammar of quest, adventure, marvel, disguise, and courtly testing."}, {"id": "084ee3aa-bc14-48ce-9a21-5609a1e9bbe2", "type": "subtopic", "title": "Sir Gawain and poetic craft", "children": [{"id": "79153fd8-0c66-458a-8b54-80fa865c099a", "type": "concept", "title": "alliterative revival"}, {"id": "3ee35cf4-8618-4eb2-9990-66f5853339af", "type": "concept", "title": "bob and wheel"}, {"id": "953f292c-d5de-4a2f-aa75-b1f597acd723", "type": "concept", "title": "green symbolism"}, {"id": "bf393d92-5520-4712-acc5-0c18f5bf5e63", "type": "concept", "title": "games, exchanges, and tests"}], "description": "Students close-read the poem's alliterative style, bob-and-wheel stanza, seasonal structure, and symbolic economy."}, {"id": "3a83ec3f-d806-45ea-a4e7-14e5125a0a1c", "type": "subtopic", "title": "Ethics, gender, and identity", "children": [{"id": "8f567f2b-5e12-426e-9148-e07e6782dee6", "type": "concept", "title": "chivalric virtue"}, {"id": "c0333f16-a3be-4d16-b5b5-651a53f08b51", "type": "concept", "title": "courtly desire"}, {"id": "f13ad1ce-684f-46ea-8135-4922e1ac9a2f", "type": "concept", "title": "confession and shame"}, {"id": "9de05591-e87d-4f22-b773-a8486580c6bf", "type": "concept", "title": "masculinity and vulnerability"}], "description": "Students examine how romance stages ideals and their breakdown."}]}, {"id": "227d5719-01c2-4a1e-bac6-941017e7a0c9", "type": "topic", "title": "Chaucer and The Canterbury Tales", "description": "Students study Chaucer as poet, translator, court worker, satirist, and formal experimenter. The Canterbury Tales becomes a social, linguistic, generic, and ethical laboratory.", "children": [{"id": "e0d21cfb-7e4c-48b8-bf94-472c6634394d", "type": "subtopic", "title": "Chaucer's language and literary career", "children": [{"id": "1924aa45-ce52-418a-93fc-074164d07ff0", "type": "concept", "title": "London English"}, {"id": "d60b0afd-7ab2-4e8a-84c2-125de4d189a7", "type": "concept", "title": "Italian and French influences"}, {"id": "26899d53-41e0-429d-96e7-3305cd3a1a21", "type": "concept", "title": "courtly and bureaucratic contexts"}, {"id": "f330e055-9b6b-4457-b66e-a198f50cc506", "type": "concept", "title": "Troilus, dream visions, and Canterbury"}], "description": "Students learn Chaucer's place in Middle English literary culture and European traditions."}, {"id": "4902c34a-3b54-4a0b-9dfb-db04202bf933", "type": "subtopic", "title": "Pilgrimage, genre, and social satire", "children": [{"id": "d107aef1-3420-4cf6-8047-cdafe6d34123", "type": "concept", "title": "General Prologue estates satire"}, {"id": "41d96015-f2b6-4079-b2e6-d9b6fbb95672", "type": "concept", "title": "pilgrimage as narrative device"}, {"id": "5eff2ce4-7c29-45a7-9083-23f8e3b37e3b", "type": "concept", "title": "genre competition"}, {"id": "f9f8d7f1-fb86-4a5e-9f0b-3d250650ff47", "type": "concept", "title": "social rank and performance"}], "description": "Students analyze how the frame narrative creates a mobile community of competing voices."}, {"id": "71a2c37e-b183-4f21-9641-c23d1df4da0c", "type": "subtopic", "title": "Tales, voice, and interpretation", "children": [{"id": "928824a1-8558-4b2e-9c80-533775c83f0c", "type": "concept", "title": "Miller and fabliau"}, {"id": "98b36d33-d1ce-4e53-9767-26befc4516a8", "type": "concept", "title": "Wife of Bath and authority"}, {"id": "e83df829-a3c3-4bf9-9961-fea3a1c3027c", "type": "concept", "title": "Pardoner and performance"}, {"id": "6a064d39-7309-43f0-a779-123b6b132ecc", "type": "concept", "title": "Knight, Clerk, Prioress, and others"}], "description": "Students practice reading individual tales through speaker, genre, irony, and audience."}]}, {"id": "76ca2311-aa93-4ca3-9420-8d67d5ee3789", "type": "topic", "title": "Allegory and Dream Vision: Pearl, Piers Plowman, and Medieval Meaning", "description": "This unit introduces allegory as a flexible medieval mode for theology, ethics, social critique, grief, and desire. Students learn to read personification, vision, and symbolic structure carefully.", "children": [{"id": "e2c523da-0837-4c04-9b82-f4c1990d96a5", "type": "subtopic", "title": "Dream vision conventions", "children": [{"id": "3b8fa36c-abea-4c4b-a58f-f62370084af2", "type": "concept", "title": "dreamer-narrator"}, {"id": "7de8e365-f3bf-420d-a9ef-713b97e149e3", "type": "concept", "title": "vision guides"}, {"id": "fe0f9ce5-3621-4dbf-ae7f-33b6c5db918f", "type": "concept", "title": "authority and confusion"}, {"id": "3446bc94-8ecf-4b20-a929-5a44136f17e7", "type": "concept", "title": "awakening and unresolved meaning"}], "description": "Students understand why dreams were powerful frames for revelation, uncertainty, and interpretive testing."}, {"id": "87ba8bf8-2a29-4109-9800-25030d8be87a", "type": "subtopic", "title": "Pearl and devotional allegory", "children": [{"id": "b2e86b85-4d9d-466b-aadf-6cab0611b656", "type": "concept", "title": "numerical structure"}, {"id": "5de3f892-cfac-416b-99d7-f14d17b10d00", "type": "concept", "title": "maiden and dreamer"}, {"id": "7f45a03f-286d-46bf-9d80-4182df18c115", "type": "concept", "title": "paradise and loss"}, {"id": "81e8451d-dc97-4092-ab7e-9ba5b81197c8", "type": "concept", "title": "alliteration and stanza pattern"}], "description": "Students read Pearl as grief poem, theological meditation, and jewel-like formal artifact."}, {"id": "08d543e8-33f0-422b-b13f-41da6291d12b", "type": "subtopic", "title": "Piers Plowman and social critique", "children": [{"id": "7ad37c07-182c-4ed7-a6f2-7702cc032898", "type": "concept", "title": "Will the dreamer"}, {"id": "796f178a-fbb6-48f1-9c73-6145d83ca8b2", "type": "concept", "title": "Dowel, Dobet, Dobest"}, {"id": "ca2f4c70-6edd-45e0-a4dd-bb9284f8feed", "type": "concept", "title": "labor and poverty"}, {"id": "fb756a19-bb92-4ad8-aab0-2a1d21fc2ddd", "type": "concept", "title": "church reform and justice"}], "description": "Students study allegory as a mode for institutional, ethical, and political argument."}]}, {"id": "4bb48647-6be8-42ff-9d20-4492845a2746", "type": "topic", "title": "Arthurian Tradition, Courtly Culture, and Transnational Romance", "description": "Students place Arthurian literature in a larger transnational tradition of French, Welsh, English, and later medieval adaptation. The unit shows how stories travel across languages, media, and ideologies.", "children": [{"id": "a2260a5e-b39e-4efe-b7b0-ac675d8ff4de", "type": "subtopic", "title": "Arthurian origins and circulation", "children": [{"id": "54031e6c-c2ad-4cc9-9fde-8895d2312858", "type": "concept", "title": "Geoffrey of Monmouth"}, {"id": "8c00e169-f79b-4b9f-b9bc-bb56fc9b84a4", "type": "concept", "title": "Wace and Layamon"}, {"id": "c49026e5-12fa-41aa-b881-ea276dbf794b", "type": "concept", "title": "French romance cycles"}, {"id": "db447329-6a0c-4f22-8b18-894b923e93c9", "type": "concept", "title": "Malory and late medieval compilation"}], "description": "Students trace how Arthurian materials move through chronicle, romance, manuscript, and later reception."}, {"id": "e6377040-c65c-408a-aa5c-1668aebe537a", "type": "subtopic", "title": "Courtly love and chivalric conflict", "children": [{"id": "760e6647-5b55-417c-a398-d2de949119eb", "type": "concept", "title": "Lancelot and Guinevere"}, {"id": "b58fee33-0e07-4a50-87f3-820ce547c8e2", "type": "concept", "title": "Tristan tradition"}, {"id": "9111b5bb-a565-4c4f-bb91-3f8a253ad044", "type": "concept", "title": "courtly service"}, {"id": "8cea26b6-ec24-4871-8cf6-fbcc85f2c5c7", "type": "concept", "title": "honor versus desire"}], "description": "Students learn how romance explores desire, loyalty, adultery, violence, and reputation."}, {"id": "88b98615-67d4-428a-8f57-a3e81613f624", "type": "subtopic", "title": "Arthurian afterlives", "children": [{"id": "9046ae65-ffbf-4787-b358-aed06e3c189b", "type": "concept", "title": "medievalism"}, {"id": "c4d48720-78d0-46d0-ab5a-7e5b1b18362f", "type": "concept", "title": "Victorian revival"}, {"id": "70254a68-e8c0-464d-be58-bc3e13240697", "type": "concept", "title": "modern fantasy"}, {"id": "890d5906-0d00-4194-b4f8-a9095dd32eda", "type": "concept", "title": "film, games, and adaptation"}], "description": "Students consider how medieval Arthur becomes a resource for later nationalism, fantasy, empire, and popular culture."}]}, {"id": "5196026b-58c0-4f7f-bb9a-ab4d1a44c27a", "type": "topic", "title": "Medieval Religious Writing, Devotion, and Mysticism", "description": "This unit treats religious writing as imaginative, affective, political, and literary. Students read devotional texts, saints' lives, sermons, visions, and mystical writing as crafted forms of spiritual experience.", "children": [{"id": "49514a05-d185-4ed8-8d19-5d7c5a591256", "type": "subtopic", "title": "Devotional genres", "children": [{"id": "ae0f28de-9b53-478d-ad10-8423c67b7608", "type": "concept", "title": "saints' lives"}, {"id": "955164f4-faa1-421b-8727-2b1655078a38", "type": "concept", "title": "meditations and prayers"}, {"id": "914b84bc-177c-4f58-bff6-7d4bd83cf9e9", "type": "concept", "title": "sermons and exempla"}, {"id": "f325e04e-4d8e-43f9-b3c8-540de9ff0fb1", "type": "concept", "title": "Passion devotion"}], "description": "Students learn the forms through which medieval readers practiced piety and moral reflection."}, {"id": "811f8bad-0b08-478b-9088-d05b8c9708d8", "type": "subtopic", "title": "Mystical writing", "children": [{"id": "7475b64d-a5d1-4246-ba94-6d12a8599bd0", "type": "concept", "title": "Julian of Norwich"}, {"id": "07f84d9f-64cf-4bed-8e73-aa407215e873", "type": "concept", "title": "Margery Kempe"}, {"id": "d3388b66-1e7b-46dd-a6f7-06db9f294523", "type": "concept", "title": "visionary authority"}, {"id": "69f478db-e095-44b4-9917-cc6396df216f", "type": "concept", "title": "affect and embodiment"}], "description": "Students examine how writers describe bodily, affective, and visionary encounters with the divine."}, {"id": "5e8f2ee0-2665-4bc6-9bda-50ef0c3e3343", "type": "subtopic", "title": "Religion and social order", "children": [{"id": "207044d8-2610-4001-abf3-3e7d38592482", "type": "concept", "title": "monastic and lay devotion"}, {"id": "7eb5eb60-c256-459b-a9fc-da17144e2a46", "type": "concept", "title": "Lollardy and dissent"}, {"id": "7a65d41d-cc5b-4ea6-a23b-50b7df51bf2c", "type": "concept", "title": "confession and pastoral care"}, {"id": "c10351f8-8eea-4ea9-94a8-efc17a5efd40", "type": "concept", "title": "pilgrimage and relic culture"}], "description": "Students connect devotional texts to institutions, reform, gender, literacy, and lay practice."}]}, {"id": "0fb10c67-70b1-40d0-953f-df26e9730b63", "type": "topic", "title": "Medieval Drama, Performance, Orality, and Public Culture", "description": "Students study medieval drama and performance as public, embodied, civic, and religious literary culture. This unit emphasizes performance contexts and the relation between text, voice, body, and community.", "children": [{"id": "4e8b092f-0734-4eb4-ace1-fb376da42804", "type": "subtopic", "title": "Drama and liturgy", "children": [{"id": "265acfb1-0fdf-4368-9c93-a5e8af91bd22", "type": "concept", "title": "cycle plays"}, {"id": "cd98f1e6-fe3c-4eb7-9f0f-580b87b08fa9", "type": "concept", "title": "mystery plays"}, {"id": "fcb8d040-bcfd-4e7a-8eb5-c603ee63621f", "type": "concept", "title": "miracle plays"}, {"id": "6cc923c1-d87a-4be2-a915-e70d0914cf6f", "type": "concept", "title": "liturgical origins and civic staging"}], "description": "Students learn how biblical drama and liturgical performance shaped public religious imagination."}, {"id": "90f128eb-1305-47d5-b9a3-49ab100288cb", "type": "subtopic", "title": "Performance and audience", "children": [{"id": "30331395-b81f-46f2-a9fb-33b20ddff4b8", "type": "concept", "title": "pageant wagons"}, {"id": "a41bc52c-3a13-4469-9420-502fa152860e", "type": "concept", "title": "guilds and civic identity"}, {"id": "9687c89d-68c5-4970-b131-4adda34123bc", "type": "concept", "title": "comic and sacred registers"}, {"id": "2a0690bc-99f4-407b-943c-d7fe354d76f4", "type": "concept", "title": "embodied interpretation"}], "description": "Students analyze how staging, voice, gesture, and audience participation create meaning."}, {"id": "c2779c4f-5b36-45d7-bb77-1ef50b3825ef", "type": "subtopic", "title": "Orality and memory", "children": [{"id": "b724bbde-3108-4b98-9b70-bc1950a4fae1", "type": "concept", "title": "recitation and song"}, {"id": "e17ed8ce-34b0-425d-97a5-3df52536c76e", "type": "concept", "title": "sermon and storytelling"}, {"id": "f4718aa5-a4e3-4aa0-b356-7ad389acedce", "type": "concept", "title": "memory arts"}, {"id": "ba0ce5eb-6788-46ff-a266-eaf2f5a044f6", "type": "concept", "title": "oral-formulaic traditions"}], "description": "Students study oral performance alongside written textuality rather than as its opposite."}]}, {"id": "c6210f39-3060-4186-8e9d-827e8748fc0a", "type": "topic", "title": "Women Writers, Gender, Class, and Authority", "description": "This unit centers gendered authorship, religious authority, domestic life, labor, class, and social voice. Students learn how medieval women and gendered subjects negotiate authority within restrictive institutions.", "children": [{"id": "28fb1676-5de9-4287-a6df-ebdb3f9d4c51", "type": "subtopic", "title": "Women authors and visionary authority", "children": [{"id": "31569cb1-49e4-4b4c-9b4d-4b7ff28e95fb", "type": "concept", "title": "revelation and experience"}, {"id": "4d189b73-435a-47de-92a6-f1c4b76faa84", "type": "concept", "title": "dictation and collaboration"}, {"id": "587c07c4-763d-4d7a-89a5-d67bd79042c0", "type": "concept", "title": "tears and affect"}, {"id": "80bfcc0d-2ebc-4c91-b5dd-4c0d6dc7c289", "type": "concept", "title": "orthodoxy and suspicion"}], "description": "Students study how writers such as Julian of Norwich and Margery Kempe authorize voice through revelation, suffering, and community."}, {"id": "7214db04-0e76-48e5-b6a5-f657e247a73a", "type": "subtopic", "title": "Gender, class, and social roles", "children": [{"id": "12feb3ab-012a-47b7-bfb9-f228af52f840", "type": "concept", "title": "estate satire"}, {"id": "7ecb2a57-de69-4b9a-b299-1f4d83012808", "type": "concept", "title": "marriage debate"}, {"id": "904ecf3a-142b-49a1-9e89-8830ac1891dc", "type": "concept", "title": "household labor"}, {"id": "74c9bafe-618f-41af-ad12-6ed3de7baf42", "type": "concept", "title": "clerical misogyny and resistance"}], "description": "Students examine how texts construct femininity, masculinity, marriage, labor, and social rank."}, {"id": "c24fdb37-a388-4488-89f0-e58afd863a4e", "type": "subtopic", "title": "Intersectional medieval studies", "children": [{"id": "4a1fbce5-e464-4640-a834-ad396af88156", "type": "concept", "title": "race and religious difference"}, {"id": "e5c363ad-7942-43f0-9ef8-a90a0573a0b2", "type": "concept", "title": "poverty and labor"}, {"id": "cae9e265-0359-4500-b156-fdaabc0b15e8", "type": "concept", "title": "body and sanctity"}, {"id": "2dd5c725-e4fd-478f-9d9b-07507c547cac", "type": "concept", "title": "regional and linguistic identity"}], "description": "Students connect gender to class, religion, race, disability, and geography in medieval textual worlds."}]}, {"id": "78c2b220-920b-4f47-b35c-eb8482b8eacd", "type": "topic", "title": "Medieval Prose, Chronicle, Travel, and Knowledge Writing", "description": "This unit broadens the course beyond poetry by examining prose genres that preserve history, travel, instruction, spirituality, politics, and practical knowledge.", "children": [{"id": "056ba847-bd60-47f1-9b16-09eacdd8b426", "type": "subtopic", "title": "Chronicle and history writing", "children": [{"id": "17afd79d-e77d-43f9-a0ed-eea794b34e66", "type": "concept", "title": "chronicle form"}, {"id": "cc3df1dd-2abc-4243-ac86-3cdfd5491119", "type": "concept", "title": "genealogy and kingship"}, {"id": "dd2c9b13-89a9-46de-9a15-f183e1f9426c", "type": "concept", "title": "national origin stories"}, {"id": "af34fab6-2cb7-4f63-8c9d-da64f7630931", "type": "concept", "title": "history and providence"}], "description": "Students learn how medieval prose constructs collective memory and political legitimacy."}, {"id": "fce4fbbc-f113-45f6-a7ef-227614550de5", "type": "subtopic", "title": "Travel and encounter", "children": [{"id": "0b9729fd-b460-43ac-91d9-cfc93750d932", "type": "concept", "title": "Mandeville tradition"}, {"id": "fdc14d7a-3683-4fbb-bb9a-0275e3d00d18", "type": "concept", "title": "pilgrimage accounts"}, {"id": "30729c2b-4250-4e31-9590-727ca103797b", "type": "concept", "title": "marvels and ethnography"}, {"id": "39e2f782-5a09-4e92-b5ae-1c619c4d613d", "type": "concept", "title": "maps and imagined geographies"}], "description": "Students examine how travel writing represents geography, marvels, religious difference, and world knowledge."}, {"id": "add50627-4e07-4c06-87ad-38ab83ea90e6", "type": "subtopic", "title": "Instructional and practical prose", "children": [{"id": "5ae4978f-99e1-42f4-8c3c-155c1e814ae6", "type": "concept", "title": "conduct books"}, {"id": "61de4581-e89a-4483-aa81-c364d9d08455", "type": "concept", "title": "medical and scientific writing"}, {"id": "5d771684-ddab-4650-95d5-50642980c1b5", "type": "concept", "title": "pastoral manuals"}, {"id": "da98fe26-cb94-4868-ab0f-c9f3e9dfd3c6", "type": "concept", "title": "household and legal texts"}], "description": "Students see prose as a vehicle for ethics, medicine, conduct, devotion, and governance."}]}, {"id": "22fe84ae-b8f8-4176-83e4-d7c6274337eb", "type": "topic", "title": "Manuscript Culture, Textuality, Codicology, and Paleography", "description": "Students learn that medieval literature survives as material text. This unit introduces manuscript production, scribal labor, textual variation, page layout, book use, and the basics of reading manuscripts.", "children": [{"id": "f7b13190-7e50-494b-9fe4-77fddbe7ad1e", "type": "subtopic", "title": "Codicology and book production", "children": [{"id": "317efb4f-22e9-40ef-8324-c0d3a23c8301", "type": "concept", "title": "parchment and paper"}, {"id": "d10ce0ef-0e0a-43ef-b8a8-87502f6b8df1", "type": "concept", "title": "quires and binding"}, {"id": "506fe99d-b8e7-4d97-be0f-fe0a9ee3e86e", "type": "concept", "title": "rubrication and illumination"}, {"id": "03e350ef-5383-4c10-81e5-0bd5aba98f75", "type": "concept", "title": "mise-en-page"}], "description": "Students study how books were made and how material form shapes interpretation."}, {"id": "a8f4ae81-617b-427e-a868-7c83eef293ac", "type": "subtopic", "title": "Scribes, readers, and textual variation", "children": [{"id": "e623c289-b3d0-477d-8739-8dccd853af98", "type": "concept", "title": "scribal copying"}, {"id": "d06535bd-bac9-485a-b3ce-4ef5cf3ccee4", "type": "concept", "title": "marginalia and annotation"}, {"id": "8678e7ad-ac16-4e3b-934b-2670f3063944", "type": "concept", "title": "variants and witnesses"}, {"id": "784f4ad5-9c55-460a-be0b-8b252a15996a", "type": "concept", "title": "editing medieval texts"}], "description": "Students learn why medieval texts often exist in multiple versions and why variation is evidence rather than error."}, {"id": "2e4a0dec-c396-4157-81c6-ffba0ae0d491", "type": "subtopic", "title": "Paleography and manuscript description", "children": [{"id": "39c44fbc-2e1b-4d17-b5c5-fddd26543a14", "type": "concept", "title": "letterforms and abbreviations"}, {"id": "c050315b-c250-420a-b213-f3fa535f782b", "type": "concept", "title": "hands and dating"}, {"id": "6fc347a2-50d2-480f-96be-6ede31f2c001", "type": "concept", "title": "catalog records"}, {"id": "9b8ffeeb-fe53-4211-97aa-784c0c58ce9e", "type": "concept", "title": "digital facsimiles"}], "description": "Students gain introductory skills for identifying scripts and describing manuscripts responsibly."}]}, {"id": "a7746b97-7e44-4d40-8c48-a7fbc78b1113", "type": "topic", "title": "Medievalism, Reception, and Research Methods", "description": "The final unit asks how the Middle Ages have been edited, translated, taught, adapted, misused, and reimagined. Students turn course knowledge into research questions and responsible critical projects.", "children": [{"id": "d9d3a171-265e-4e5d-bc40-13f1908d2b51", "type": "subtopic", "title": "Medievalism and modern reception", "children": [{"id": "9b59c713-e340-4fc4-8656-c6b31af7bebb", "type": "concept", "title": "Victorian medievalism"}, {"id": "8e895fef-9611-4389-8777-0cd540019e84", "type": "concept", "title": "fantasy and gaming"}, {"id": "64efbab0-5532-437f-9f38-d7ad7f404777", "type": "concept", "title": "nationalism and myth"}, {"id": "383119ca-a063-4a0f-9b7f-4165cd330531", "type": "concept", "title": "popular and extremist misuses"}], "description": "Students examine how later cultures invent and reuse the medieval for art, nation, fantasy, politics, and identity."}, {"id": "aa3e868d-6d29-44b1-bf10-da24f9f61b3e", "type": "subtopic", "title": "Research tools and scholarly methods", "children": [{"id": "00a39a21-1ad2-4f36-bdf2-6c99d04c0ca6", "type": "concept", "title": "Middle English Dictionary"}, {"id": "9adb8a59-b6fe-494b-bc9d-4a61942f0524", "type": "concept", "title": "bibliographies and databases"}, {"id": "2edeb387-c0e1-4200-94b7-46072664c8c9", "type": "concept", "title": "manuscript catalogues"}, {"id": "7e38dcc9-9813-482c-a061-cddcceac7016", "type": "concept", "title": "edition choice and citation"}], "description": "Students learn how to move from curiosity to an evidence-based medieval literature project."}, {"id": "8143c3ca-16e1-4df9-80a0-625cb8ad6627", "type": "subtopic", "title": "Final project design", "children": [{"id": "d226f8a3-a596-446d-ab9e-fa2d2b82cc8b", "type": "concept", "title": "research question"}, {"id": "860357f6-884e-42bc-9a2f-37830354de8f", "type": "concept", "title": "primary and secondary sources"}, {"id": "b590f6a2-0121-4aeb-bbbb-aa4987852cce", "type": "concept", "title": "translation and edition rationale"}, {"id": "ca6bd966-4436-4de0-8e59-6d77a15c9cb8", "type": "concept", "title": "presentation and revision"}], "description": "Students synthesize close reading, context, translation, and material text into a polished argument or public-facing project."}]}], "dbBacked": true}$medljson$::jsonb,
